# __NAME__ - one-time game setup (generated by MC Manager).
#
# Adds one launcher entry per server setup ("__NAME__ - <world>") to
# .minecraft (and TLauncher's game folder), downloads its mods into a separate
# folder, and installs a small agent that re-syncs mods every time you press
# Play. Your own mods, versions, shaders and settings are not changed.
#
# Run again any time to repair. Run with /uninstall to remove everything.

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor 3072

$Base = '__BASE__'
$Token = '__TOKEN__'
$Slug = '__SLUG__'
$Name = '__NAME__'
$Api = "$Base/client/$Token"
$Root = Join-Path $env:APPDATA ".$Slug"
$Utf8 = New-Object System.Text.UTF8Encoding($false)
$Uninstall = "$env:MCM_ARGS" -match 'uninstall'
$SharedKinds = @('shaderpacks', 'resourcepacks')

function Say($text, $color = 'Gray') { Write-Host $text -ForegroundColor $color }
function Fwd($path) { $path -replace '\\', '/' }
function Write-Text($file, $text) {
    New-Item -ItemType Directory -Force -Path (Split-Path $file) | Out-Null
    [IO.File]::WriteAllText($file, $text, $Utf8)
}
function Json-Str($text) {
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append('"')
    foreach ($ch in $text.ToCharArray()) {
        $code = [int]$ch
        if ($ch -eq '"') { [void]$sb.Append('\"') }
        elseif ($ch -eq '\') { [void]$sb.Append('\\') }
        elseif ($code -lt 32 -or $code -gt 126) { [void]$sb.Append(('\u{0:x4}' -f $code)) }
        else { [void]$sb.Append($ch) }
    }
    [void]$sb.Append('"')
    $sb.ToString()
}

# .minecraft plus TLauncher's custom game folder, if it has one.
function Get-GameDirs {
    $dirs = @((Join-Path $env:APPDATA '.minecraft'))
    $tl = Join-Path $env:APPDATA '.tlauncher\tlauncher-2.0.properties'
    if (Test-Path -LiteralPath $tl) {
        foreach ($line in Get-Content -LiteralPath $tl) {
            if ($line -match '^minecraft\.gamedir=(.+)$') {
                $dir = $Matches[1] -replace '\\:', ':' -replace '\\\\', '\'
                if ($dir -and (Test-Path -LiteralPath $dir)) { $dirs += (Resolve-Path -LiteralPath $dir).Path }
            }
        }
    }
    $seen = @{}
    foreach ($dir in $dirs) {
        $key = $dir.TrimEnd('\').ToLowerInvariant()
        if (-not $seen.ContainsKey($key)) { $seen[$key] = $true; $dir.TrimEnd('\') }
    }
}

function Test-Hash($file, $spec) {
    $parts = $spec -split ':', 2
    $algo = @{ sha1 = 'SHA1'; sha256 = 'SHA256'; sha512 = 'SHA512' }[$parts[0]]
    if (-not $algo -or -not (Test-Path -LiteralPath $file)) { return $false }
    (Get-FileHash -LiteralPath $file -Algorithm $algo).Hash -eq $parts[1]
}

# Downloads from the first URL that works (Modrinth's CDN or the manager) and checks the hash.
function Get-VerifiedFile($urls, $dest, $spec) {
    $part = "$dest.part"
    New-Item -ItemType Directory -Force -Path (Split-Path $dest) | Out-Null
    foreach ($u in $urls) {
        if ($u -match '^https?://') {
            if ($u -notmatch '^https://cdn\.modrinth\.com/') { continue }
            $url = $u
        } else { $url = "$Api/$u" }
        try {
            Invoke-WebRequest -Uri $url -OutFile $part -UseBasicParsing -TimeoutSec 120
            if (Test-Hash $part $spec) { Move-Item -LiteralPath $part -Destination $dest -Force; return $true }
            Say "    checksum mismatch ($url)" Yellow
        } catch { Say "    $url failed: $($_.Exception.Message)" DarkYellow }
    }
    Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
    $false
}

function Read-Owned {
    $file = Join-Path $Root 'owned.txt'
    if (Test-Path -LiteralPath $file) { @(Get-Content -LiteralPath $file -Encoding UTF8 | Where-Object { $_ }) } else { @() }
}
function Save-Owned($list) { Write-Text (Join-Path $Root 'owned.txt') ((@($list | Sort-Object -Unique) -join "`n") + "`n") }

# Start and end index of the profile object whose lastVersionId is $vid, or $null.
function Find-ProfileObject($text, $vid) {
    $m = [regex]::Match($text, '"lastVersionId"\s*:\s*"' + [regex]::Escape($vid) + '"')
    if (-not $m.Success) { return $null }
    $depth = 0; $start = -1
    for ($i = $m.Index - 1; $i -ge 0; $i--) {
        $c = $text[$i]
        if ($c -eq '}') { $depth++ }
        elseif ($c -eq '{') { if ($depth -eq 0) { $start = $i; break }; $depth-- }
    }
    if ($start -lt 0) { return $null }
    $depth = 0
    for ($j = $start; $j -lt $text.Length; $j++) {
        $c = $text[$j]
        if ($c -eq '{') { $depth++ }
        elseif ($c -eq '}') { $depth--; if ($depth -eq 0) { return @($start, $j) } }
    }
    $null
}

function Set-Profile($game, $vid, $label) {
    $file = Join-Path $game 'launcher_profiles.json'
    $now = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ')
    # No "icon": launchers then show their Fabric look instead of the vanilla grass block.
    $entry = '"' + $vid + '": {"name": ' + (Json-Str $label) + ', "type": "custom", "lastVersionId": "' + $vid + '", "created": "' + $now + '", "lastUsed": "' + $now + '"}'
    if (-not (Test-Path -LiteralPath $file)) {
        Write-Text $file ('{"profiles": {' + $entry + '}, "settings": {}, "version": 3}')
        return
    }
    $text = [IO.File]::ReadAllText($file)
    $backup = "$file.$Slug.bak"
    if (-not (Test-Path -LiteralPath $backup)) { Copy-Item -LiteralPath $file -Destination $backup }
    # Launchers may re-key profiles (SKLauncher uses random ids), so find ours by its version.
    $span = Find-ProfileObject $text $vid
    if ($span) {
        # Keep the player's own settings; refresh the name and drop the old grass icon.
        $old = $text.Substring($span[0], $span[1] - $span[0] + 1)
        $obj = ([regex]'("name"\s*:\s*)"(?:[^"\\]|\\.)*"').Replace($old, '${1}' + (Json-Str $label).Replace('$', '$$'), 1)
        $obj = [regex]::Replace($obj, '\s*"icon"\s*:\s*"[^"]*"\s*,', '')
        $obj = [regex]::Replace($obj, ',\s*"icon"\s*:\s*"[^"]*"', '')
        if ($obj -eq $old) { return }
        $text = $text.Substring(0, $span[0]) + $obj + $text.Substring($span[1] + 1)
    } else {
        $m = [regex]::Match($text, '"profiles"\s*:\s*\{')
        if (-not $m.Success) { Say "    could not read $file; pick the version '$vid' manually" Yellow; return }
        $rest = $text.Substring($m.Index + $m.Length)
        $sep = if ($rest -match '^\s*\}') { '' } else { ', ' }
        $text = $text.Insert($m.Index + $m.Length, $entry + $sep)
    }
    Write-Text $file $text
}

function Remove-Profiles($game) {
    $file = Join-Path $game 'launcher_profiles.json'
    if (-not (Test-Path -LiteralPath $file)) { return }
    $text = [IO.File]::ReadAllText($file)
    $original = $text
    # Every profile whose version is one of ours, whatever key the launcher gave it.
    while ($true) {
        $m = [regex]::Match($text, '"lastVersionId"\s*:\s*"(' + [regex]::Escape($Slug) + '-[^"]*)"')
        if (-not $m.Success) { break }
        $span = Find-ProfileObject $text $m.Groups[1].Value
        if (-not $span) { break }
        $key = [regex]::Match($text.Substring(0, $span[0]), '"[^"]*"\s*:\s*$')
        if (-not $key.Success) { break }
        $text = $text.Substring(0, $key.Index) + $text.Substring($span[1] + 1)
        $text = [regex]::Replace($text, ',(\s*[,}])', '$1')
        $text = [regex]::Replace($text, '\{(\s*),', '{$1')
    }
    if ($text -ne $original) { Write-Text $file $text }
}

function Invoke-Uninstall {
    Say "Removing $Name from this PC..." Cyan
    foreach ($game in Get-GameDirs) {
        $versions = Join-Path $game 'versions'
        if (Test-Path -LiteralPath $versions) {
            Get-ChildItem -LiteralPath $versions -Directory -Filter "$Slug-*" | Remove-Item -Recurse -Force
        }
        Remove-Profiles $game
    }
    foreach ($path in Read-Owned) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $Root) { Remove-Item -LiteralPath $Root -Recurse -Force }
    Say 'Done. Your own mods and settings were not touched.' Green
}

function Invoke-Setup {
    Say "$Name - game setup" Cyan
    Say "Contacting the server at $Base ..."
    try {
        $sync = (Invoke-WebRequest -Uri "$Api/sync.txt" -UseBasicParsing -TimeoutSec 15 -Headers @{ 'X-MCM-Agent' = 'setup' }).Content
    } catch {
        Say 'Could not reach the server. Make sure Tailscale is connected, then run this again.' Red
        Say $_.Exception.Message DarkGray
        return
    }
    if ($sync -is [byte[]]) { $sync = $Utf8.GetString($sync) }

    $agent = $null; $setups = @(); $files = @(); $server = $null
    foreach ($raw in ($sync -split "`n")) {
        $p = $raw.TrimEnd("`r") -split "`t"
        switch ($p[0]) {
            'server' { $server = @{ Name = $p[1]; Address = $p[2] } }
            'agent' { $agent = @{ File = $p[1]; Sha = $p[2] } }
            'setup' { $setups += @{ Id = $p[1]; Vid = $p[2]; Label = $p[3]; Mc = $p[4]; Active = $p[7] -eq '1'; Hash = $p[8] } }
            'file' { $files += @{ Setup = $p[1]; Kind = $p[2]; Name = $p[3]; Hash = $p[4]; Urls = @($p[6..($p.Length - 1)]) } }
        }
    }
    if (-not $setups.Count) { Say 'The server has no Fabric setup to sync yet. Ask an admin.' Yellow; return }
    New-Item -ItemType Directory -Force -Path $Root | Out-Null
    Write-Text (Join-Path $Root 'client.properties') ("base=$Base`ntoken=$Token`nslug=$Slug`n")

    if ($agent) {
        $agentFile = Join-Path $Root $agent.File
        if (-not (Test-Hash $agentFile "sha256:$($agent.Sha)")) {
            Say 'Downloading the sync agent'
            if (-not (Get-VerifiedFile @("agent/$($agent.File)") $agentFile "sha256:$($agent.Sha)")) { Say 'Agent download failed; run this again.' Red; return }
        }
    }

    $games = @(Get-GameDirs)
    $owned = [Collections.ArrayList]@(Read-Owned)
    $versionsState = @()
    foreach ($setup in $setups) {
        Say ''
        Say "== $($setup.Label) (Minecraft $($setup.Mc))" White
        $inst = Join-Path $Root "instances\$($setup.Id)"
        $modsDir = Join-Path $inst 'mods'
        New-Item -ItemType Directory -Force -Path $modsDir, (Join-Path $inst 'extra-mods') | Out-Null
        $mine = @($files | Where-Object { $_.Setup -eq $setup.Id })
        $wanted = @{}
        foreach ($f in ($mine | Where-Object { $_.Kind -eq 'mods' })) {
            $wanted[$f.Name.ToLowerInvariant()] = $true
            $dest = Join-Path $modsDir $f.Name
            if (Test-Hash $dest $f.Hash) { continue }
            Say "  + $($f.Name)"
            if (-not (Get-VerifiedFile $f.Urls $dest $f.Hash)) { Say "  could not download $($f.Name); it will be retried when you press Play" Yellow }
        }
        Get-ChildItem -LiteralPath $modsDir -File | Where-Object { -not $wanted.ContainsKey($_.Name.ToLowerInvariant()) } | ForEach-Object {
            Say "  - $($_.Name)" DarkGray
            Remove-Item -LiteralPath $_.FullName -Force
        }

        $version = $null
        try { $version = (Invoke-WebRequest -Uri "$Api/version/$($setup.Id).json" -UseBasicParsing -TimeoutSec 30).Content } catch { Say "  version file unavailable: $($_.Exception.Message)" Yellow }
        if ($version -is [byte[]]) { $version = $Utf8.GetString($version) }

        foreach ($game in $games) {
            foreach ($f in ($mine | Where-Object { $SharedKinds -contains $_.Kind })) {
                $dest = Join-Path $game "$($f.Kind)\$($f.Name)"
                if (Test-Path -LiteralPath $dest) {
                    if (-not $owned.Contains($dest) -or (Test-Hash $dest $f.Hash)) { continue }
                }
                Say "  + $($f.Kind)\$($f.Name)"
                if (Get-VerifiedFile $f.Urls $dest $f.Hash) { if (-not $owned.Contains($dest)) { [void]$owned.Add($dest) } }
            }
            if ($version) {
                $text = $version.Replace('@@CLIENT@@', (Fwd $Root)).Replace('@@GAME@@', (Fwd $game))
                Write-Text (Join-Path $game "versions\$($setup.Vid)\$($setup.Vid).json") $text
                Set-Profile $game $setup.Vid $setup.Label
                $versionsState += "$($setup.Vid)`t$($setup.Hash)`t$game"
            }
        }
    }

    # Remove entries of setups the server no longer has.
    $keep = @{}
    foreach ($setup in $setups) { $keep[$setup.Vid] = $true; $keep[$setup.Id] = $true }
    foreach ($game in $games) {
        $versions = Join-Path $game 'versions'
        if (Test-Path -LiteralPath $versions) {
            Get-ChildItem -LiteralPath $versions -Directory -Filter "$Slug-*" | Where-Object { -not $keep.ContainsKey($_.Name) } | Remove-Item -Recurse -Force
        }
    }
    $instances = Join-Path $Root 'instances'
    Get-ChildItem -LiteralPath $instances -Directory | Where-Object { -not $keep.ContainsKey($_.Name) } | Remove-Item -Recurse -Force
    Save-Owned $owned
    Write-Text (Join-Path $Root 'versions.txt') (($versionsState -join "`n") + "`n")

    $active = $setups | Where-Object { $_.Active } | Select-Object -First 1
    Say ''
    Say 'All set!' Green
    if ($active) { Say "Open your launcher (TLauncher, SKLauncher, ...), pick '$($active.Label)' and press Play." Green }
    if ($server -and $server.Address) { Say "The server ($($server.Address)) is added to your Multiplayer list on first launch." }
    Say 'Mods update automatically every time you press Play. Keep Tailscale connected.'
    Say "Your own extra client mods for this server can go in: $Root\instances\<setup>\extra-mods"
}

try {
    if ($Uninstall) { Invoke-Uninstall } else { Invoke-Setup }
} catch {
    Say "Setup failed: $($_.Exception.Message)" Red
}
